// @ts-nocheck
import { FormEvent, ReactNode, useEffect, useState } from 'react'
import { App as CapacitorApp } from '@capacitor/app'
import OrderCreation from './OrderCreation'
import MessagingPanel from './MessagingPanel'
import AuthAccess from './AuthAccess'
import AppSelect from './AppSelect'
import ReceiptPanel from './ReceiptPanel'
import InvoicePanel from './InvoicePanel'
import ManagerInvoiceSendPanel from './ManagerInvoiceSendPanel'
import ReceivingPanel from './ReceivingPanel'
import InventoryPanel from './InventoryOverview'
import InventoryRequestsPanel from './InventoryRequestsPanel'
import StockRequestPanel from './StockRequestPanel'
import SalesOrderPanel from './SalesOrderPanel'
import WorkerOrderPanel from './WorkerOrderPanel'
import ReorderPanel from './ReorderPanel'
import OperationsReportPanel from './OperationsReportPanel'
import ColdChainDashboardPanel from './ColdChainDashboardPanel'
import TransferPanel from './TransferPanel'
import WarehouseOverview from './WarehouseOverview'
import CheckoutPanel from './CheckoutPanel'
import CounterStockPanel from './CounterStockPanel'
import AIHelpPanel from './AIHelpPanel'
import { CopilotSidebar, ExpiryWastePanel, ReportsPanel, SettingsPanel } from './WarehouseModules'
import { NativeAppEffects } from './MobilePrimitives'
import NetworkActivityEffects from './NetworkActivityEffects'
import { getOrders, markNotificationRead } from './api'
import { AlertTriangle, ArrowDownToLine, ArrowRight, ArrowUpRight, Barcode as BarcodeIcon, Bell, Bot as BotIcon, Boxes, CheckCircle2, ClipboardList, LayoutDashboard, LogOut, Menu, PackageCheck, PackageSearch, Plus, RefreshCw, Search, ShoppingCart, Store as StoreIcon, Truck, UserRound, Users, X } from 'lucide-react'
import { approveOrder, approveRegistration, approveTransfer, AuthUser, confirmInvoice, confirmOrderReceipt, createOrder, createProduct, createPurchaseOrder, createTransfer, DashboardData, Customer, deleteUser, fulfillOrder, generateInvoice, getCustomers, getCurrentUser, getDashboard, getExpiringInventory, getInventory, getInvoices, getNotifications, getOrder, getProducts, getRegistrationRequests, getSignupWarehouses, getSuppliers, getUsers, getWarehouses, Invoice, InventoryRecord, login, logout, Notification, Product, ProductInput, Role, rejectOrder, rejectRegistration, rejectTransfer, receivePurchaseOrder, register, sendInvoice, Supplier, User, Warehouse as WarehouseRecord } from './api'

type View = 'Overview' | 'Orders' | 'Invoices' | 'Stock Requests' | 'Inventory' | 'Scanner' | 'Receiving' | 'Counter Stock' | 'Transfers' | 'Expiry & Waste' | 'Reorder' | 'Reports' | 'AI Copilot' | 'Notifications' | 'Team' | 'Settings'
const roleName: Record<Role, string> = { manager: 'Manager', warehouse_worker: 'Warehouse worker' }
const demoDashboard: DashboardData = { total_products: 0, total_inventory_records: 0, pending_sales_orders: 0, approved_sales_orders: 0, pending_purchase_orders: 0, unread_notifications: 0, low_stock_products: [], expiring_batches: [], inventory_intelligence: [] }

function App() {
  const [user, setUser] = useState<AuthUser | null>(null); const [checking, setChecking] = useState(true); const [view, setView] = useState<View>('Overview'); const [toast, setToast] = useState(''); const [menu, setMenu] = useState(false); const [confirmSignout, setConfirmSignout] = useState(false)
  useEffect(() => { const token = localStorage.getItem('pantryos_token'); if (!token) { setChecking(false); return }; void getCurrentUser().then(setUser).catch(() => logout()).finally(() => setChecking(false)) }, [])
  useEffect(() => { const expired = () => setUser(null); window.addEventListener('pantryos:session-expired', expired); return () => window.removeEventListener('pantryos:session-expired', expired) }, [])
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 3200); return () => window.clearTimeout(timer) }, [toast])
  useEffect(() => { const signout = (event: MouseEvent) => { if ((event.target as HTMLElement).closest('.avatar')) setConfirmSignout(true) }; document.addEventListener('click', signout); return () => document.removeEventListener('click', signout) }, [])
  useEffect(() => { const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape') setMenu(false) }; window.addEventListener('keydown', closeOnEscape); return () => window.removeEventListener('keydown', closeOnEscape) }, [])
  useEffect(() => { let handle: { remove: () => Promise<void> } | undefined; void CapacitorApp.addListener('backButton', ({ canGoBack }) => { if (menu || document.querySelector('.mobile-more-sheet.is-open, .copilot-drawer-scrim')) { setMenu(false); window.dispatchEvent(new Event('pantryos:close-overlays')); return }; if (canGoBack) window.history.back(); else void CapacitorApp.exitApp() }).then((listener) => { handle = listener }); return () => { void handle?.remove() } }, [menu])
  if (checking) return <div className="auth-loading"><PackageCheck size={27} /><span>Connecting to PantryOS...</span></div>
  if (!user) return <AuthAccess onLogin={setUser} />
  const allowed = navigationFor(user.role); const activeView = allowed.some((item) => item.id === view) ? view : allowed[0].id
  const navigate = (next: View) => { setView(next); setMenu(false) }
  return <div className="app-shell"><aside className={`sidebar ${menu ? 'is-open' : ''}`}><div className="brand"><div className="brand-mark"><PackageCheck size={19} /></div><div><strong>PantryOS</strong><span>Food warehouse</span></div></div><nav className="main-nav"><p className="nav-caption">Operations</p>{allowed.map((item) => <button className={`nav-item ${activeView === item.id ? 'active' : ''}`} key={item.id} onClick={() => navigate(item.id)}><item.icon size={18} /><span>{item.label}</span></button>)}</nav><div className="sidebar-footer"><div className="support-icon"><UserRound size={13} /></div><div><strong>{user.username}</strong><span>{roleName[user.role]}</span></div><button className="logout-button" onClick={() => setConfirmSignout(true)} aria-label="Sign out" title="Sign out"><LogOut size={15} /></button></div></aside><main className="main-content"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMenu(!menu)} aria-label="Open menu"><Menu size={19} /></button><div className="breadcrumbs"><strong>{activeView}</strong></div><div className="top-actions"><button className="icon-button" onClick={() => navigate('Notifications')} aria-label="Notifications"><Bell size={19} /></button><div className="avatar">{user.username.slice(0, 2).toUpperCase()}</div></div></header><div className="page-wrap"><Workspace view={activeView} role={user.role} onToast={setToast} onNavigate={navigate} /><footer className="page-footer"><span>PantryOS · {roleName[user.role]} access</span><span>Connected to backend API</span></footer></div></main>{confirmSignout && <ConfirmDialog title="Sign out of PantryOS?" text="You will return to the login screen. Your account and saved data will remain unchanged." onCancel={() => setConfirmSignout(false)} onConfirm={() => { logout(); setUser(null); setConfirmSignout(false) }} />}{toast && <div className="toast"><CheckCircle2 size={17} />{toast}<button onClick={() => setToast('')} aria-label="Dismiss"><X size={14} /></button></div>}</div>
}

function navigationFor(role: Role) {
  const overview = { id: 'Overview' as View, label: 'Dashboard', icon: LayoutDashboard }
  const orders = { id: 'Orders' as View, label: 'Orders', icon: ClipboardList }
  const invoices = { id: 'Invoices' as View, label: 'Invoices', icon: ArrowUpRight }
  const stockRequests = { id: 'Stock Requests' as View, label: 'Stock requests', icon: PackageSearch }
  const inventory = { id: 'Inventory' as View, label: 'Inventory', icon: Boxes }
  const scanner = { id: 'Scanner' as View, label: 'Scanner', icon: BarcodeIcon }
  const receiving = { id: 'Receiving' as View, label: 'Receiving', icon: ArrowDownToLine }
  const counter = { id: 'Counter Stock' as View, label: 'Counter Stock', icon: StoreIcon }
  const transfers = { id: 'Transfers' as View, label: 'Transfers', icon: Truck }
  const aiCopilot = { id: 'AI Copilot' as View, label: 'AI Help', icon: BotIcon }
  const expiry = { id: 'Expiry & Waste' as View, label: 'Expiry & Waste', icon: AlertTriangle }
  const notifications = { id: 'Notifications' as View, label: 'Notifications', icon: Bell }
  const base = [overview, orders, scanner, inventory, receiving, expiry, notifications]
  if (role === 'manager') return [...base, stockRequests, invoices, transfers, counter, { id: 'Reorder' as View, label: 'Reorder', icon: RefreshCw }, { id: 'Reports' as View, label: 'Reports', icon: ClipboardList }, aiCopilot, { id: 'Team' as View, label: 'Team', icon: Users }, { id: 'Settings' as View, label: 'Settings', icon: Users }]
  return [...base, stockRequests, aiCopilot]
}
function Workspace({ view, role, onToast, onNavigate }: { view: View; role: Role; onToast: (message: string) => void; onNavigate: (view: View) => void }) { return <><NativeAppEffects /><NetworkActivityEffects /><MobileNavigation view={view} role={role} onNavigate={onNavigate} /><CopilotSidebar onToast={onToast} /><WorkspaceContent view={view} role={role} onToast={onToast} onNavigate={onNavigate} /></> }
function WorkspaceContent({ view, role, onToast, onNavigate }: { view: View; role: Role; onToast: (message: string) => void; onNavigate: (view: View) => void }) {
  if (view === 'Overview') return <><WarehouseOverview onNavigate={onNavigate} />{role === 'manager' && <ColdChainDashboardPanel onToast={onToast} onNavigate={onNavigate} />}</>
  if (view === 'Orders') return <>{role === 'manager' ? <><OrderCreation onToast={onToast} /><SalesOrderPanel role={role} onToast={onToast} /><ReceiptPanel onToast={onToast} /></> : <WorkerOrderPanel onToast={onToast} />}</>
  if (view === 'Invoices') return <><InvoicePanel role={role} onToast={onToast} />{role === 'manager' && <ManagerInvoiceSendPanel onToast={onToast} />}</>
  if (view === 'Stock Requests') return <StockRequestPanel role={role} onToast={onToast} />
  if (view === 'Inventory') return <><InventoryPanel onToast={onToast} role={role} /><InventoryRequestsPanel onToast={onToast} role={role} /></>
  if (view === 'Scanner') return <CheckoutPanel onToast={onToast} />
  if (view === 'Receiving') return <ReceivingPanel onToast={onToast} role={role} />
  if (view === 'Counter Stock') return <CounterStockPanel onToast={onToast} role={role} />
  if (view === 'Transfers') return <TransferPanel role={role} onToast={onToast} />
  if (view === 'Expiry & Waste') return <ExpiryWastePanel onToast={onToast} role={role} />
  if (view === 'Reorder') return <ReorderPanel onToast={onToast} />
  if (view === 'Reports') return <><OperationsReportPanel onToast={onToast} /><ReportsPanel onToast={onToast} role={role} /></>
  if (view === 'AI Copilot') return <AIHelpPanel onToast={onToast} role={role} />
  if (view === 'Settings') return <SettingsPanel />
  if (view === 'Team') return <><TeamManagement onToast={onToast} /><RegistrationRequests onToast={onToast} /></>
  return <><MessagingPanel role={role} /><NotificationsInteractive /></>
}
function MobileNavigation({ view, role, onNavigate }: { view: View; role: Role; onNavigate: (view: View) => void }) { const [moreOpen, setMoreOpen] = useState(false); useEffect(() => { const close = () => setMoreOpen(false); window.addEventListener('pantryos:close-overlays', close); return () => window.removeEventListener('pantryos:close-overlays', close) }, []); const allowed = navigationFor(role); const primary = allowed.filter((item) => ['Overview', 'Inventory', 'Scanner'].includes(item.id)).slice(0, 3); const more = allowed.filter((item) => !primary.some((primaryItem) => primaryItem.id === item.id)); const go = (next: View) => { setMoreOpen(false); onNavigate(next) }; return <><div className={`mobile-more-scrim ${moreOpen ? 'is-visible' : ''}`} onClick={() => setMoreOpen(false)} /><div className={`mobile-more-sheet ${moreOpen ? 'is-open' : ''}`} role="dialog" aria-label="More warehouse modules"><div className="sheet-title"><strong>Warehouse modules</strong><button className="icon-button" aria-label="Close menu" onClick={() => setMoreOpen(false)}><X size={19} /></button></div>{more.map((item) => <button className={`sheet-item ${view === item.id ? 'active' : ''}`} key={item.id} onClick={() => go(item.id)}><item.icon size={19} /><span>{item.label}</span><ArrowRight size={16} /></button>)}</div><nav className="mobile-bottom-nav" aria-label="Primary navigation">{primary.map((item) => <button className={view === item.id ? 'active' : ''} key={item.id} onClick={() => go(item.id)}><item.icon size={20} /><span>{item.label === 'Dashboard' ? 'Home' : item.label}</span></button>)}<button className={moreOpen ? 'active' : ''} onClick={() => setMoreOpen((open) => !open)}><Menu size={20} /><span>More</span></button></nav></> }
function Header({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <section className="module-header"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div>{action && <div className="module-actions">{action}</div>}</section> }
function Button({ children, onClick, variant = 'primary', type = 'button' }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'subtle'; type?: 'button' | 'submit' }) { return <button className={`button ${variant}`} type={type} onClick={onClick}>{children}</button> }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label>{label}{children}</label> }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty-state"><PackageSearch size={28} /><strong>{title}</strong><span>{text}</span></div> }

function Login({ onLogin }: { onLogin: (user: AuthUser) => void }) { const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false); async function submit(event: FormEvent) { event.preventDefault(); setLoading(true); setError(''); try { onLogin(await login(username, password)) } catch (e) { setError(e instanceof Error ? e.message : 'Invalid username or password') } finally { setLoading(false) } } return <div className="auth-shell"><div className="auth-visual"><div className="auth-brand"><div className="brand-mark"><PackageCheck size={19} /></div><strong>PantryOS</strong></div><div className="auth-visual-copy"><p className="eyebrow">Food warehouse management</p><h1>Every batch accounted for.</h1><p>Inventory, orders, receiving, transfers, and invoices in one focused workspace.</p></div></div><div className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><p className="eyebrow">Secure access</p><h2>Sign in to PantryOS</h2><p className="auth-intro">Use an account registered in the backend.</p><Field label="Username"><input autoFocus required value={username} onChange={(e) => setUsername(e.target.value)} /></Field><Field label="Password"><input required type="password" value={password} onChange={(e) => setPassword(e.target.value)} /></Field>{error && <div className="auth-error"><AlertTriangle size={15} />{error}</div>}<Button type="submit">{loading ? 'Signing in...' : 'Continue'} <ArrowRight size={16} /></Button></form></div></div> }

function LegacyAccessScreen({ onLogin }: { onLogin: (user: AuthUser) => void }) {
  const [mode, setMode] = useState<'login' | 'signup'>('login'); const [username, setUsername] = useState(''); const [fullName, setFullName] = useState(''); const [password, setPassword] = useState(''); const [role, setRole] = useState<Role>('manager'); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [loading, setLoading] = useState(false)
  async function submit(event: FormEvent) { event.preventDefault(); setLoading(true); setError(''); setMessage(''); try { if (mode === 'login') { onLogin(await login(username, password)) } else { const result = await register({ username, full_name: fullName, password, role }); setMessage(result.message); setPassword('') } } catch (e) { setError(e instanceof Error ? e.message : 'Request failed') } finally { setLoading(false) } }
  return <div className="auth-shell"><div className="auth-visual"><div className="auth-brand"><div className="brand-mark"><PackageCheck size={19} /></div><strong>PantryOS</strong></div><div className="auth-visual-copy"><p className="eyebrow">Food warehouse management</p><h1>Every batch accounted for.</h1><p>Inventory, orders, receiving, transfers, and invoices in one focused workspace.</p></div></div><div className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-tabs"><button type="button" className={mode === 'login' ? 'active' : ''} onClick={() => { setMode('login'); setError(''); setMessage('') }}>Sign in</button><button type="button" className={mode === 'signup' ? 'active' : ''} onClick={() => { setMode('signup'); setError(''); setMessage('') }}>Sign up</button></div><p className="eyebrow">{mode === 'login' ? 'Secure access' : 'Request access'}</p><h2>{mode === 'login' ? 'Sign in to PantryOS' : 'Create an account'}</h2><p className="auth-intro">{mode === 'login' ? 'Use an approved account from the warehouse system.' : 'A manager must approve your role before you can sign in.'}</p>{mode === 'signup' && <Field label="Full name"><input required value={fullName} onChange={(e) => setFullName(e.target.value)} /></Field>}<Field label="Username"><input autoFocus required minLength={3} value={username} onChange={(e) => setUsername(e.target.value)} /></Field>{mode === 'signup' && <Field label="Requested role"><AppSelect value={role} onChange={(e) => setRole(e.target.value as Role)}><option value="warehouse_worker">Warehouse worker</option><option value="manager">Manager</option></AppSelect></Field>}<Field label="Password"><input required minLength={8} type="password" value={password} onChange={(e) => setPassword(e.target.value)} /></Field>{error && <div className="auth-error"><AlertTriangle size={15} />{error}</div>}{message && <div className="auth-success"><CheckCircle2 size={15} />{message}</div>}<Button type="submit">{loading ? 'Please wait...' : mode === 'login' ? 'Continue' : 'Submit signup request'} <ArrowRight size={16} /></Button></form></div></div>
}

function Overview({ onNavigate }: { onNavigate: (view: View) => void }) { const [data, setData] = useState<DashboardData>(demoDashboard); const [error, setError] = useState(''); const load = async () => { try { setData(await getDashboard()); setError('') } catch (e) { setError(e instanceof Error ? e.message : 'Dashboard unavailable') } }; useEffect(() => { void load() }, []); return <><Header eyebrow="Operations dashboard" title="Warehouse overview" description="A live summary of food stock and operational exceptions." action={<Button variant="subtle" onClick={() => void load()}><RefreshCw size={16} /> Refresh</Button>} />{error ? <div className="panel info-banner"><AlertTriangle size={18} /><div><strong>Dashboard unavailable</strong><span>{error}</span></div></div> : <><section className="stat-grid">{[['Products', data.total_products, PackageSearch], ['Inventory records', data.total_inventory_records, Boxes], ['Pending sales orders', data.pending_sales_orders, ClipboardList], ['Pending purchase orders', data.pending_purchase_orders, Truck]].map(([label, value, Icon]) => { const IconComponent = Icon as typeof PackageSearch; return <article className="stat-card sage" key={label as string}><div className="stat-card-top"><span>{label as string}</span><div className="stat-icon"><IconComponent size={18} /></div></div><div className="stat-value">{Number(value).toLocaleString()}</div><div className="stat-foot">From dashboard API</div></article>})}</section><section className="panel data-panel"><div className="table-toolbar"><div><p className="eyebrow">Expiry control</p><h2>Expiring batches</h2></div><button className="link-button" onClick={() => onNavigate('Inventory')}>Open inventory <ArrowUpRight size={15} /></button></div>{data.expiring_batches.length ? <div className="data-table"><div className="data-head"><span>Product</span><span>Batch</span><span>Quantity</span><span>Expiry</span></div>{data.expiring_batches.map((item) => <div className="data-row compact" key={item.batch_number}><strong>{item.product_name}</strong><span>{item.batch_number}</span><span>{item.quantity}</span><span className="warning-text">{item.expiry_date}</span></div>)}</div> : <Empty title="No batches expiring soon" text="The backend returned no active batches in the seven-day window." />}</section></>}</> }

function Inventory({ role, onToast }: { role: Role; onToast: (message: string) => void }) { const [products, setProducts] = useState<Product[]>([]); const [inventory, setInventory] = useState<InventoryRecord[]>([]); const [expiring, setExpiring] = useState<Awaited<ReturnType<typeof getExpiringInventory>>['items']>([]); const [search, setSearch] = useState(''); const [show, setShow] = useState(false); const [form, setForm] = useState({ name: '', category: '', quantity: '', unit: '', price: '' }); const load = async () => { try { const [p, i, e] = await Promise.all([getProducts(), getInventory(), getExpiringInventory()]); setProducts(p.products); setInventory(i.inventory); setExpiring(e.items) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not load inventory') } }; useEffect(() => { void load() }, []); const rows = products.filter((p) => `${p.name} ${p.category}`.toLowerCase().includes(search.toLowerCase())); async function submit(event: FormEvent) { event.preventDefault(); const quantity = Number(form.quantity); const price = Number(form.price); if (!form.name.trim() || !form.category.trim() || !form.unit.trim() || !Number.isFinite(quantity) || !Number.isFinite(price) || quantity < 0 || price < 0) { onToast('Enter a valid product, quantity, unit, and price'); return } try { await createProduct({ name: form.name.trim(), category: form.category.trim(), quantity, unit: form.unit.trim(), price }); setShow(false); setForm({ name: '', category: '', quantity: '', unit: '', price: '' }); await load(); onToast('Product added to inventory') } catch (e) { onToast(e instanceof Error ? e.message : 'Could not create product') } } return <><Header eyebrow="Stock control" title="Inventory" description="Products, stock records, and expiry data returned by the backend." action={<>{role === 'warehouse_worker' && <Button onClick={() => setShow(true)}><Plus size={16} /> Add product</Button>}<Button variant="subtle" onClick={() => void load()}><RefreshCw size={16} /> Refresh</Button></>} /><div className="module-toolbar"><label className="search-box wide"><Search size={16} /><input placeholder="Search products" value={search} onChange={(e) => setSearch(e.target.value)} /></label><span>{rows.length} products · {inventory.length} stock records</span></div><section className="panel data-panel"><div className="table-toolbar"><div><p className="eyebrow">Products</p><h2>Catalogue</h2></div></div>{rows.length ? <div className="data-table"><div className="data-head"><span>Product</span><span>Category</span><span>Quantity</span><span>Unit</span><span>Price</span></div>{rows.map((p) => <div className="data-row" key={p.product_id}><div className="table-product"><div className="product-thumb"><PackageSearch size={16} /></div><strong>{p.name}</strong></div><span>{p.category}</span><span>{p.quantity}</span><span>{p.unit}</span><span>${Number(p.price).toFixed(2)}</span></div>)}</div> : <Empty title="No products returned" text="The catalogue is empty or the backend did not return data." />}</section><section className="panel data-panel"><div className="table-toolbar"><div><p className="eyebrow">FEFO watch</p><h2>Expiring inventory</h2></div></div>{expiring.length ? <div className="data-table"><div className="data-head"><span>Batch</span><span>Product ID</span><span>Warehouse</span><span>Quantity</span><span>Expiry</span></div>{expiring.map((item) => <div className="data-row" key={item.inventory_id}><strong>{item.batch_number}</strong><span>{item.product_id}</span><span>{item.warehouse_id}</span><span>{item.quantity}</span><span className="warning-text">{item.expiry_date}</span></div>)}</div> : <Empty title="No expiring stock" text="No inventory batches expire within the next seven days." />}</section>{show && <Modal title="Add product to inventory" onClose={() => setShow(false)}><form className="form-grid" onSubmit={submit}><Field label="Name"><input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></Field><Field label="Category"><input required value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></Field><Field label="Quantity"><input required type="number" min="0" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /></Field><Field label="Unit"><input required placeholder="kg, box, litre..." value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })} /></Field><Field label="Price"><input required type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></Field><div className="form-actions"><Button variant="subtle" onClick={() => setShow(false)}>Cancel</Button><Button type="submit">Add product</Button></div></form></Modal>}</> }

function LegacyOrderLookup({ role, onToast }: { role: Role; onToast: (message: string) => void }) { const [customers, setCustomers] = useState<Customer[]>([]); const [products, setProducts] = useState<Product[]>([]); const [customer, setCustomer] = useState(''); const [product, setProduct] = useState(''); const [quantity, setQuantity] = useState(1); const [lookup, setLookup] = useState(''); const [order, setOrder] = useState<Awaited<ReturnType<typeof getOrder>> | null>(null); useEffect(() => { void Promise.all([getCustomers(), getProducts()]).then(([c, p]) => { setCustomers(c.customers); setProducts(p.products) }).catch(() => undefined) }, []); async function submit(event: FormEvent) { event.preventDefault(); try { await createOrder({ customer_id: Number(customer), items: [{ product_id: Number(product), quantity }] }); onToast('Sales order created') } catch (e) { onToast(e instanceof Error ? e.message : 'Could not create order') } } async function lookupOrder(event: FormEvent) { event.preventDefault(); try { setOrder(await getOrder(Number(lookup))) } catch (e) { onToast(e instanceof Error ? e.message : 'Order not found') } } const action = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); onToast(message); if (lookup) setOrder(await getOrder(Number(lookup))) } catch (e) { onToast(e instanceof Error ? e.message : 'Order action failed') } }; return <><Header eyebrow="Sales orders" title="Orders" description="Create orders or inspect one order by its backend ID." />{role === 'manager' && <section className="panel workflow-card"><p className="eyebrow">Create order</p><h2>New sales order</h2><form className="form-grid" onSubmit={submit}><Field label="Customer"><AppSelect required value={customer} onChange={(e) => setCustomer(e.target.value)}><option value="">Select customer</option>{customers.map((c) => <option key={c.customer_id} value={c.customer_id}>{c.name}</option>)}</AppSelect></Field><Field label="Product"><AppSelect required value={product} onChange={(e) => setProduct(e.target.value)}><option value="">Select product</option>{products.map((p) => <option key={p.product_id} value={p.product_id}>{p.name}</option>)}</AppSelect></Field><Field label="Quantity"><input type="number" min="1" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} /></Field><div className="form-actions"><Button type="submit"><ShoppingCart size={16} /> Create order</Button></div></form></section>}<section className="panel workflow-card"><p className="eyebrow">Order lookup</p><h2>Order #{order?.order_id ?? '—'}</h2><form className="inline-form" onSubmit={lookupOrder}><input required type="number" min="1" placeholder="Order ID" value={lookup} onChange={(e) => setLookup(e.target.value)} /><Button type="submit">Find order</Button></form>{order && <div className="order-result"><span className={`pill ${order.status === 'approved' ? 'ready' : order.status === 'rejected' ? 'urgent' : 'pending'}`}>{order.status}</span><span>{order.items.length} line items</span>{role === 'manager' && order.status === 'pending' && <><button className="row-action" onClick={() => void action(() => approveOrder(order.order_id), 'Order approved')}>Approve</button><button className="row-action danger" onClick={() => void action(() => rejectOrder(order.order_id), 'Order rejected')}>Reject</button></>}{role === 'warehouse_worker' && order.status === 'approved' && <button className="row-action" onClick={() => void action(() => fulfillOrder(order.order_id), 'Order fulfilled')}>Fulfill</button>}{order.status === 'fulfilled' && <button className="row-action" onClick={() => void action(() => generateInvoice(order.order_id), 'Invoice generated')}>Generate invoice</button>}</div>}</section></> }

function LegacyReceiving({ role, onToast }: { role: Role; onToast: (message: string) => void }) { const [suppliers, setSuppliers] = useState<Supplier[]>([]); const [products, setProducts] = useState<Product[]>([]); const [warehouses, setWarehouses] = useState<WarehouseRecord[]>([]); const [supplier, setSupplier] = useState(''); const [product, setProduct] = useState(''); const [quantity, setQuantity] = useState(1); const [purchaseId, setPurchaseId] = useState(''); const [warehouse, setWarehouse] = useState(''); const [batch, setBatch] = useState({ number: '', manufactured: '', expiry: '' }); useEffect(() => { void Promise.all([getSuppliers(), getProducts(), getWarehouses()]).then(([s, p, w]) => { setSuppliers(s.suppliers); setProducts(p.products); setWarehouses(w.warehouses) }).catch(() => undefined) }, []); async function create(event: FormEvent) { event.preventDefault(); try { await createPurchaseOrder({ supplier_id: Number(supplier), items: [{ product_id: Number(product), quantity }] }); onToast('Purchase order created') } catch (e) { onToast(e instanceof Error ? e.message : 'Could not create purchase order') } } async function receive(event: FormEvent) { event.preventDefault(); try { await receivePurchaseOrder(Number(purchaseId), { warehouse_id: Number(warehouse), items: [{ product_id: Number(product), quantity, batch_number: batch.number, manufacturing_date: batch.manufactured, expiry_date: batch.expiry }]} ); onToast('Purchase order received') } catch (e) { onToast(e instanceof Error ? e.message : 'Could not receive purchase order') } } return <><Header eyebrow="Inbound stock" title="Receiving" description="Create purchase orders and receive them into a warehouse with batch dates." /><div className="workflow-grid">{role === 'manager' && <section className="panel workflow-card"><p className="eyebrow">Purchase order</p><h2>Create inbound order</h2><form className="stack-form" onSubmit={create}><Field label="Supplier"><AppSelect required value={supplier} onChange={(e) => setSupplier(e.target.value)}><option value="">Select supplier</option>{suppliers.map((s) => <option value={s.supplier_id} key={s.supplier_id}>{s.name}</option>)}</AppSelect></Field><Field label="Product"><AppSelect required value={product} onChange={(e) => setProduct(e.target.value)}><option value="">Select product</option>{products.map((p) => <option value={p.product_id} key={p.product_id}>{p.name}</option>)}</AppSelect></Field><Field label="Quantity"><input type="number" min="1" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} /></Field><Button type="submit"><Plus size={16} /> Create purchase order</Button></form></section>}{role === 'warehouse_worker' && <section className="panel workflow-card"><p className="eyebrow">Warehouse receiving</p><h2>Receive purchase order</h2><form className="stack-form" onSubmit={receive}><Field label="Purchase order ID"><input required type="number" value={purchaseId} onChange={(e) => setPurchaseId(e.target.value)} /></Field><Field label="Warehouse"><AppSelect required value={warehouse} onChange={(e) => setWarehouse(e.target.value)}><option value="">Select warehouse</option>{warehouses.map((w) => <option value={w.warehouse_id} key={w.warehouse_id}>{w.name}</option>)}</AppSelect></Field><Field label="Product"><AppSelect required value={product} onChange={(e) => setProduct(e.target.value)}><option value="">Select product</option>{products.map((p) => <option value={p.product_id} key={p.product_id}>{p.name}</option>)}</AppSelect></Field><Field label="Quantity"><input type="number" min="1" value={quantity} onChange={(e) => setQuantity(Number(e.target.value))} /></Field><Field label="Batch number"><input required value={batch.number} onChange={(e) => setBatch({ ...batch, number: e.target.value })} /></Field><Field label="Manufacturing date"><input required type="date" value={batch.manufactured} onChange={(e) => setBatch({ ...batch, manufactured: e.target.value })} /></Field><Field label="Expiry date"><input required type="date" value={batch.expiry} onChange={(e) => setBatch({ ...batch, expiry: e.target.value })} /></Field><Button type="submit"><ArrowDownToLine size={16} /> Receive stock</Button></form></section>}</div></> }

function LegacyTransfers({ role, onToast }: { role: Role; onToast: (message: string) => void }) { const [products, setProducts] = useState<Product[]>([]); const [warehouses, setWarehouses] = useState<WarehouseRecord[]>([]); const [form, setForm] = useState({ product: '', batch: '', source: '', destination: '', quantity: 1 }); const [id, setId] = useState(''); useEffect(() => { void Promise.all([getProducts(), getWarehouses()]).then(([p, w]) => { setProducts(p.products); setWarehouses(w.warehouses) }).catch(() => undefined) }, []); const run = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); onToast(message) } catch (e) { onToast(e instanceof Error ? e.message : 'Transfer action failed') } }; async function submit(e: FormEvent) { e.preventDefault(); await run(() => createTransfer({ product_id: Number(form.product), batch_id: Number(form.batch), source_warehouse_id: Number(form.source), destination_warehouse_id: Number(form.destination), quantity: form.quantity }), 'Transfer requested') } return <><Header eyebrow="Stock movement" title="Transfers" description="Request or approve transfers using the backend’s batch and warehouse IDs." />{role === 'manager' && <section className="panel workflow-card"><p className="eyebrow">Transfer request</p><h2>Move stock between warehouses</h2><form className="form-grid" onSubmit={submit}><Field label="Product"><AppSelect required value={form.product} onChange={(e) => setForm({ ...form, product: e.target.value })}><option value="">Select product</option>{products.map((p) => <option value={p.product_id} key={p.product_id}>{p.name}</option>)}</AppSelect></Field><Field label="Batch ID"><input required type="number" value={form.batch} onChange={(e) => setForm({ ...form, batch: e.target.value })} /></Field><Field label="Source warehouse"><AppSelect required value={form.source} onChange={(e) => setForm({ ...form, source: e.target.value })}><option value="">Select source</option>{warehouses.map((w) => <option value={w.warehouse_id} key={w.warehouse_id}>{w.name}</option>)}</AppSelect></Field><Field label="Destination warehouse"><AppSelect required value={form.destination} onChange={(e) => setForm({ ...form, destination: e.target.value })}><option value="">Select destination</option>{warehouses.map((w) => <option value={w.warehouse_id} key={w.warehouse_id}>{w.name}</option>)}</AppSelect></Field><Field label="Quantity"><input required type="number" min="1" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: Number(e.target.value) })} /></Field><div className="form-actions"><Button type="submit"><Truck size={16} /> Request transfer</Button></div></form></section>}{role === 'manager' && <section className="panel workflow-card"><p className="eyebrow">Approval action</p><h2>Approve or reject transfer</h2><p className="panel-intro">The backend does not expose a transfer list. Enter the transfer ID from your operational record.</p><div className="inline-form"><input type="number" min="1" placeholder="Transfer ID" value={id} onChange={(e) => setId(e.target.value)} /><Button onClick={() => void run(() => approveTransfer(Number(id)), 'Transfer approved')}>Approve</Button><Button variant="subtle" onClick={() => void run(() => rejectTransfer(Number(id)), 'Transfer rejected')}>Reject</Button></div></section>}</> }

function Invoices({ role, onToast }: { role: Role; onToast: (message: string) => void }) { const [invoices, setInvoices] = useState<Invoice[]>([]); const load = async () => { try { setInvoices((await getInvoices()).invoices) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not load invoices') } }; useEffect(() => { void load() }, []); const action = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); await load(); onToast(message) } catch (e) { onToast(e instanceof Error ? e.message : 'Invoice action failed') } }; return <><Header eyebrow="Billing" title="Invoices" description="Track generated invoices and perform only the actions allowed for your role." action={<Button variant="subtle" onClick={() => void load()}><RefreshCw size={16} /> Refresh</Button>} /><section className="panel data-panel"><div className="table-toolbar"><div><p className="eyebrow">Invoice register</p><h2>{invoices.length} invoices</h2></div></div>{invoices.length ? <div className="data-table"><div className="data-head"><span>Invoice</span><span>Order</span><span>Total</span><span>Status</span><span>Action</span></div>{invoices.map((invoice) => <div className="data-row" key={invoice.invoice_id}><strong>#{invoice.invoice_id}</strong><span>#{invoice.order_id}</span><span>${Number(invoice.total_amount).toFixed(2)}</span><span className="pill ready">{invoice.status}</span><span>{role === 'manager' && invoice.status === 'generated' && <button className="row-action" onClick={() => void action(() => sendInvoice(invoice.invoice_id), 'Invoice sent')}>Send</button>}{role === 'manager' && invoice.status === 'sent' && <button className="row-action" onClick={() => void action(() => confirmInvoice(invoice.invoice_id), 'Invoice confirmed')}>Confirm</button>}</span></div>)}</div> : <Empty title="No invoices" text="Invoices are generated from fulfilled sales orders." />}</section></> }

function TeamManagement({ onToast }: { onToast: (message: string) => void }) { const [users, setUsers] = useState<User[]>([]); const [pending, setPending] = useState<User | null>(null); const [currentUser, setCurrentUser] = useState<AuthUser | null>(null); const load = async () => { try { const [team, me] = await Promise.all([getUsers(), getCurrentUser()]); setUsers(team.users); setCurrentUser(me) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not load team') } }; useEffect(() => { void load() }, []); async function remove(password: string) { if (!pending) return; try { await deleteUser(pending.user_id, password); setPending(null); await load(); if (pending.user_id === currentUser?.user_id) { logout(); window.location.reload(); return } onToast(`${pending.username} was removed`) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not remove user') } } const managerCount = users.filter((user) => user.role === 'manager').length; return <><Header eyebrow="People" title="Team" description="Approved users returned by the backend. Password fields are never displayed." /><section className="panel data-panel"><div className="data-table"><div className="data-head"><span>Full name</span><span>Username</span><span>Role</span><span>Action</span></div>{users.length ? users.map((user) => <div className="data-row compact" key={user.user_id}><strong>{user.full_name}</strong><span>{user.username}</span><span className="role-tag">{roleName[user.role]}</span><span>{user.role === 'manager' && user.user_id !== currentUser?.user_id ? 'Protected' : <button className="row-action danger" onClick={() => setPending(user)}>{user.role === 'manager' ? 'Delete account' : 'Remove'}</button>}</span></div>) : <Empty title="No team members" text="No users were returned by the backend." />}</div></section>{pending && <RemoveUserDialog username={pending.username} isSelf={pending.user_id === currentUser?.user_id} managerCount={managerCount} onCancel={() => setPending(null)} onConfirm={(password) => void remove(password)} />}</> }
function RegistrationRequests({ onToast }: { onToast: (message: string) => void }) { const [requests, setRequests] = useState<Awaited<ReturnType<typeof getRegistrationRequests>>['requests']>([]); const load = async () => { try { setRequests((await getRegistrationRequests()).requests) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not load signup requests') } }; useEffect(() => { void load() }, []); const review = async (id: number, action: 'approve' | 'reject') => { try { if (action === 'approve') await approveRegistration(id); else await rejectRegistration(id); await load(); onToast(action === 'approve' ? 'Signup approved' : 'Signup rejected') } catch (e) { onToast(e instanceof Error ? e.message : 'Could not review signup') } }; return <section className="panel data-panel"><div className="table-toolbar"><div><p className="eyebrow">Manager approval</p><h2>Signup requests</h2></div><Button variant="subtle" onClick={() => void load()}><RefreshCw size={16} /> Refresh</Button></div>{requests.length ? <div className="data-table"><div className="data-head"><span>Applicant</span><span>Username</span><span>Requested role</span><span>Action</span></div>{requests.map((request) => <div className="data-row" key={request.request_id}><strong>{request.full_name}</strong><span>{request.username}</span><span className="role-tag">{roleName[request.role] ?? `Unsupported: ${request.role}`}</span><span className="review-actions"><button className="row-action" disabled={!roleName[request.role]} onClick={() => void review(request.request_id, 'approve')}>Approve</button><button className="row-action danger" onClick={() => void review(request.request_id, 'reject')}>Reject</button></span></div>)}</div> : <Empty title="No pending signup requests" text="New registrations will wait here for manager approval." />}</section> }
function Notifications() { const [items, setItems] = useState<Notification[]>([]); useEffect(() => { void getNotifications().then((data) => setItems(data.notifications)).catch(() => setItems([])) }, []); return <><Header eyebrow="Activity" title="Notifications" description="Notifications for the authenticated user." /><section className="notification-list">{items.length ? items.map((item) => <article className={`notification ${item.is_read ? '' : 'unread'}`} key={item.notification_id}><div className="notification-icon"><Bell size={16} /></div><div><strong>{item.title}</strong><p>{item.message}</p><span>{item.created_at}</span></div></article>) : <div className="panel"><Empty title="No notifications" text="You have no notifications returned by the backend." /></div>}</section></> }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" onMouseDown={(e) => e.stopPropagation()}><div className="modal-header"><div><p className="eyebrow">Backend resource</p><h2>{title}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={18} /></button></div>{children}</div></div> }
function ConfirmDialog({ title, text, onCancel, onConfirm }: { title: string; text: string; onCancel: () => void; onConfirm: () => void }) { return <div className="modal-backdrop" onMouseDown={onCancel}><div className="confirm-dialog" onMouseDown={(event) => event.stopPropagation()}><div className="confirm-icon"><LogOut size={18} /></div><h2>{title}</h2><p>{text}</p><div className="confirm-actions"><Button variant="subtle" onClick={onCancel}>Cancel</Button><Button onClick={onConfirm}>Sign out</Button></div></div></div> }
function RemoveUserDialog({ username, isSelf, managerCount, onCancel, onConfirm }: { username: string; isSelf: boolean; managerCount: number; onCancel: () => void; onConfirm: (password: string) => void }) { const [password, setPassword] = useState(''); const [error, setError] = useState(''); const cannotDeleteLastManager = isSelf && managerCount <= 1; function submit(event: FormEvent) { event.preventDefault(); if (isSelf && !password) { setError('Enter your password to continue'); return } onConfirm(password) } return <div className="modal-backdrop" onMouseDown={onCancel}><div className="confirm-dialog remove-dialog" onMouseDown={(event) => event.stopPropagation()}><div className="confirm-icon remove-icon"><UserRound size={18} /></div>{cannotDeleteLastManager ? <><h2>Cannot delete account</h2><p>A duplicate manager account must exist and be approved before this account can be deleted.</p><div className="confirm-actions"><Button onClick={onCancel}>Close</Button></div></> : <form onSubmit={submit}><h2>{isSelf ? 'Delete your manager account?' : `Remove ${username}?`}</h2><p>{isSelf ? 'This action is permanent. Enter your password to confirm, and you will return to the login page.' : 'This removes the account from PostgreSQL. Existing operational history will be preserved under your manager account.'}</p>{isSelf && <Field label="Password"><input autoFocus required type="password" value={password} onChange={(event) => { setPassword(event.target.value); setError('') }} /></Field>}{error && <div className="auth-error"><AlertTriangle size={15} />{error}</div>}<div className="confirm-actions"><Button variant="subtle" onClick={onCancel}>Cancel</Button><Button type="submit">{isSelf ? 'Delete account' : 'Remove user'}</Button></div></form>}</div></div> }
function Orders({ role, onToast }: { role: Role; onToast: (message: string) => void }) { const [orders, setOrders] = useState<Awaited<ReturnType<typeof getOrders>>['orders']>([]); const [selected, setSelected] = useState<Awaited<ReturnType<typeof getOrder>> | null>(null); const load = async () => { try { setOrders((await getOrders()).orders) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not load orders') } }; useEffect(() => { void load() }, []); const select = async (orderId: number) => { try { setSelected(await getOrder(orderId)) } catch (e) { onToast(e instanceof Error ? e.message : 'Could not load order') } }; const action = async (fn: () => Promise<unknown>, message: string) => { try { await fn(); await load(); if (selected) await select(selected.order_id); onToast(message) } catch (e) { onToast(e instanceof Error ? e.message : 'Order action failed') } }; return <><Header eyebrow="Sales orders" title="Orders" description="Review pending orders and perform the actions allowed for your role." /><section className="panel data-panel"><div className="table-toolbar"><div><p className="eyebrow">Order queue</p><h2>{orders.length} orders</h2></div><Button variant="subtle" onClick={() => void load()}><RefreshCw size={16} /> Refresh</Button></div>{orders.length ? <div className="data-table"><div className="data-head"><span>Order</span><span>Products</span><span>Created</span><span>Status</span><span>Action</span></div>{orders.map((item) => <div className="data-row" key={item.order_id}><strong>Order #{item.order_id}</strong><span>{item.items?.length ? item.items.map((line) => `${line.product_name} x${line.quantity}`).join(', ') : 'No items'}</span><span>{new Date(item.created_at).toLocaleString()}</span><span className={`pill ${item.status === 'approved' || item.status === 'confirmed' ? 'ready' : item.status === 'rejected' ? 'urgent' : 'pending'}`}>{item.status}</span><button className="row-action" onClick={() => void select(item.order_id)}>View</button></div>)}</div> : <Empty title="No orders" text="Orders will appear here when they are created." />}</section>{selected && <section className="panel workflow-card"><div className="table-toolbar"><div><p className="eyebrow">Selected order</p><h2>Order #{selected.order_id}</h2></div><span className={`pill ${selected.status === 'approved' || selected.status === 'confirmed' ? 'ready' : selected.status === 'rejected' ? 'urgent' : 'pending'}`}>{selected.status}</span></div><div className="order-result"><div className="order-items">{(selected.items ?? []).map((line) => <span key={line.product_id}>{line.product_name} × {line.quantity}</span>)}</div>{role === 'manager' && selected.status === 'pending' && <><button className="row-action" onClick={() => void action(() => approveOrder(selected.order_id), 'Order approved')}>Approve</button><button className="row-action danger" onClick={() => void action(() => rejectOrder(selected.order_id), 'Order rejected')}>Reject</button></>}{role === 'warehouse_worker' && selected.status === 'approved' && <button className="row-action" onClick={() => void action(() => fulfillOrder(selected.order_id), 'Order fulfilled')}>Fulfill</button>}{selected.status === 'confirmed' && <button className="row-action" onClick={() => void action(() => generateInvoice(selected.order_id), 'Invoice generated')}>Generate invoice</button>}</div></section>}</> }

function NotificationsInteractive() { const [items, setItems] = useState<Notification[]>([]); const load = async () => { try { setItems((await getNotifications()).notifications) } catch { setItems([]) } }; useEffect(() => { void load() }, []); const markRead = async (id: number) => { try { await markNotificationRead(id); await load() } catch {} }; return <><Header eyebrow="Activity" title="Notifications" description="Notifications for the authenticated user." /><section className="notification-list">{items.length ? items.map((item) => <article className={`notification ${item.is_read ? '' : 'unread'}`} key={item.notification_id}><div className="notification-icon"><Bell size={16} /></div><div><strong>{item.title}</strong><p>{item.message}</p><span>{item.created_at}</span></div>{!item.is_read && <button className="row-action" onClick={() => void markRead(item.notification_id)}>Mark read</button>}</article>) : <div className="panel"><Empty title="No notifications" text="You have no notifications returned by the backend." /></div>}</section></> }

export default App






